<script>
  // Slide-over Drawer Interactions
  const openDrawerBtn = document.getElementById('openDrawerBtn');
  const closeDrawerBtn = document.getElementById('closeDrawerBtn');
  const cancelDrawerBtn = document.getElementById('cancelDrawerBtn');
  const drawerBackdrop = document.getElementById('drawerBackdrop');
  const categoryDrawer = document.getElementById('categoryDrawer');
  const saveCategoryBtn = document.getElementById('saveCategoryBtn');

  function openDrawer() {
    drawerBackdrop.classList.remove('hidden');
    setTimeout(() => {
      drawerBackdrop.classList.remove('opacity-0');
      categoryDrawer.classList.remove('translate-x-full');
    }, 10);
  }

  function closeDrawer() {
    categoryDrawer.classList.add('translate-x-full');
    drawerBackdrop.classList.add('opacity-0');
    setTimeout(() => {
      drawerBackdrop.classList.add('hidden');
    }, 300);
  }

  if (openDrawerBtn) openDrawerBtn.addEventListener('click', openDrawer);
  if (closeDrawerBtn) closeDrawerBtn.addEventListener('click', closeDrawer);
  if (cancelDrawerBtn) cancelDrawerBtn.addEventListener('click', closeDrawer);
  if (drawerBackdrop) drawerBackdrop.addEventListener('click', closeDrawer);
  if (saveCategoryBtn) saveCategoryBtn.addEventListener('click', closeDrawer);

  // Search & Filter Interactions
  const catSearchInput = document.getElementById('catSearchInput');
  const filterPills = document.querySelectorAll('.filter-pill');
  const tableRows = document.querySelectorAll('#categoryTableBody tr');

  if (catSearchInput) {
    catSearchInput.addEventListener('input', function(e) {
      const term = e.target.value.toLowerCase();
      tableRows.forEach(row => {
        const text = row.innerText.toLowerCase();
        row.style.display = text.includes(term) ? '' : 'none';
      });
    });
  }

  filterPills.forEach(pill => {
    pill.addEventListener('click', function() {
      filterPills.forEach(p => {
        p.classList.remove('bg-surface-container-lowest', 'text-on-surface', 'font-semibold', 'shadow-sm');
        p.classList.add('text-secondary');
      });
      this.classList.add('bg-surface-container-lowest', 'text-on-surface', 'font-semibold', 'shadow-sm');
      this.classList.remove('text-secondary');

      const filter = this.getAttribute('data-filter');
      tableRows.forEach(row => {
        const status = row.getAttribute('data-status');
        const isFlagship = row.getAttribute('data-flagship') === 'true';

        if (filter === 'all') {
          row.style.display = '';
        } else if (filter === 'active') {
          row.style.display = status === 'active' ? '' : 'none';
        } else if (filter === 'draft') {
          row.style.display = status === 'draft' ? '' : 'none';
        } else if (filter === 'flagship') {
          row.style.display = isFlagship ? '' : 'none';
        }
      });
    });
  });

  // Reorder & Export micro-actions
  const reorderBtn = document.getElementById('reorderBtn');
  if (reorderBtn) {
    reorderBtn.addEventListener('click', () => {
      const icon = reorderBtn.querySelector('.material-symbols-outlined');
      icon.classList.add('rotate-180');
      setTimeout(() => icon.classList.remove('rotate-180'), 400);
    });
  }

  const exportBtn = document.getElementById('exportBtn');
  if (exportBtn) {
    exportBtn.addEventListener('click', () => {
      exportBtn.classList.add('bg-tertiary-fixed/30');
      setTimeout(() => exportBtn.classList.remove('bg-tertiary-fixed/30'), 800);
    });
  }
</script></main></div><script>
(() => {
 const dialog=document.getElementById('brand-dialog'),form=document.getElementById('brand-form'),nameInput=document.getElementById('brand-name-input'),descInput=document.getElementById('brand-description-input');let editing=null;
 const close=()=>{dialog.classList.add('hidden');dialog.classList.remove('flex');};
 const open=(row=null)=>{editing=row;document.getElementById('brand-dialog-title').textContent=row?'Edit brand':'Add brand';nameInput.value=row?.querySelector('.brand-name')?.textContent||'';descInput.value=row?.cells[1]?.textContent||'';dialog.classList.remove('hidden');dialog.classList.add('flex');};
 document.getElementById('add-brand-button')?.addEventListener('click',()=>open());document.querySelectorAll('.edit-brand-button').forEach(button=>button.addEventListener('click',()=>open(button.closest('tr'))));document.getElementById('close-brand-dialog')?.addEventListener('click',close);document.getElementById('cancel-brand-dialog')?.addEventListener('click',close);
 form?.addEventListener('submit',event=>{event.preventDefault();const name=nameInput.value.trim();if(!name)return;const row=editing||document.createElement('tr');if(!editing){row.innerHTML='<td class="p-3"><strong class="brand-name"></strong></td><td class="p-3"></td><td class="p-3">Unassigned</td><td class="p-3">Draft</td><td class="p-3 text-right"><button type="button" class="edit-brand-button rounded-lg p-2 hover:bg-surface-container">Edit</button></td>';document.getElementById('brand-table-body').prepend(row);row.querySelector('.edit-brand-button').addEventListener('click',()=>open(row));}row.querySelector('.brand-name').textContent=name;row.cells[1].textContent=descInput.value.trim();close();});
})();
</script>
<script>
document.getElementById('category-image-upload')?.addEventListener('change',event=>{const file=event.target.files?.[0];document.getElementById('category-image-name').textContent=file?file.name:'';});
</script>
<script>
(() => {
 const body=document.getElementById('categoryTableBody');const drawer=document.getElementById('categoryDrawer');const nameField=drawer?.querySelector('input[type="text"]');const save=document.getElementById('saveCategoryBtn');let activeRow=null;
 document.querySelectorAll('#categoryTableBody [title="Edit Taxonomy"]').forEach(button=>button.addEventListener('click',()=>{activeRow=button.closest('tr');const heading=activeRow.querySelector('.font-headline-sm');if(heading&&nameField)nameField.value=heading.textContent.trim();}));
 document.getElementById('openDrawerBtn')?.addEventListener('click',()=>{activeRow=null;if(nameField)nameField.value='';});
 save?.addEventListener('click',()=>{const name=nameField?.value.trim();if(!name||!body)return;if(activeRow){const heading=activeRow.querySelector('.font-headline-sm');if(heading)heading.textContent=name;}else{const row=document.createElement('tr');row.dataset.status='draft';row.dataset.flagship='false';row.className='hover:bg-surface-container-low/40 transition-colors';row.innerHTML=`<td class="py-4 pl-space-md pr-2"><span class="material-symbols-outlined text-outline">drag_indicator</span></td><td class="py-4 px-4"><div class="font-headline-sm text-headline-sm text-on-surface">${name}</div><div class="font-label-sm text-label-sm text-secondary">Draft category</div></td><td class="py-4 px-4">Unassigned</td><td class="py-4 px-4 text-center">0</td><td class="py-4 px-4">0 products</td><td class="py-4 px-4">Unpublished</td><td class="py-4 px-4">Draft</td><td class="py-4 px-4"></td><td class="py-4 px-4"></td><td class="py-4 px-4 text-right"><button type="button" title="Edit Taxonomy" class="p-1.5 rounded-lg">Edit</button></td>`;body.prepend(row);row.querySelector('[title="Edit Taxonomy"]').addEventListener('click',()=>{activeRow=row;if(nameField)nameField.value=row.querySelector('.font-headline-sm').textContent;});}});
})();
</script></body></html>






